\end{eqnarray}
In the limit $\chi \rightarrow 0,$ the equations above reduce to GR case.

\subsection{Old Prescription ($\mathcal{L}_{m} = p$)}

In order to see the discrepancy compared to the new prescription, we show the field equation and its components for the old one with $\mathcal{L}_{m}=p$ \cite{Pappas:2022gtt}. The equation is given by
\begin{equation}
G_{\mu\nu} = 8\pi T_{\mu\nu} + \chi g_{\mu\nu}T + 2\chi (T_{\mu\nu}-pg_{\mu\nu}),
\end{equation}
and 
\begin{eqnarray}
\label{mold}
m' &=& 4\pi r^2 \rho + \frac{\chi}{2}r^2(3\rho-p),\\ \nu' &=& \frac{2m+8\pi r^3 p+\chi r^3(3p-\rho)}{r(r-2m)}, \\ \label{pold} p' &=& -(\rho+p) \left(\frac{8\pi+2\chi}{8\pi+3\chi}\right)  \left[ \frac{m+4\pi r^3 p + \frac{\chi}{2}r^3 (3p-\rho)}{r(r-2m)}   \right]\nonumber \\ && +\frac{\chi}{8\pi+3\chi}\rho'.
\end{eqnarray}
It is worth noting that in obtaining the mass, metric, and TOV equations above, they use \eqref{pro} and \eqref{p2ro2}.

\subsection{Old Prescription ($\mathcal{L}_{m} = -\rho$)}

For $\mathcal{L}_{m}=-\rho$, the field equations are given by
\begin{equation}
G_{\mu\nu} = 8\pi T_{\mu\nu} + \chi g_{\mu\nu}T + 2\chi [T_{\mu\nu}+g_{\mu\nu}(2\rho+p)],
\end{equation}
and
\begin{eqnarray}
\label{moldminro}
m' &=& 4\pi r^2 \rho - \frac{\chi}{2}r^2(\rho+5p),\\ \nu' &=& \frac{2m+8\pi p r^3+\chi r^3(3\rho+7p)}{r(r-2m)}, \\ \label{poldminro} p' &=& -(\rho+p) \left(\frac{8\pi+2\chi}{8\pi-3\chi}\right)  \left[ \frac{m+4\pi r^3 p + \frac{\chi}{2}r^3 (3\rho+7p)}{r(r-2m)}   \right]\nonumber \\ && -\frac{3\chi}{8\pi+2\chi}\rho'.
